/**
 * ブラウザからエージェントの会話を呼ぶ、フレームワークに依存しない芯。
 * @flue/sdk の createFlueClient を同じオリジンの会話の URL で作り、AgentSession で状態にする。
 * ブラウザに入るので、Node の API と @flue/runtime を読み込まない。ビルドのあとに scripts/check-browser.mjs が確かめる
 */
import {
	type ConversationLiveMode,
	type CreateFlueClientOptions,
	createFlueClient,
	type FlueClient,
} from "@flue/sdk";
import { AgentSession } from "./client/agent-session";

export type {
	AgentAbortResult,
	AgentSendResult,
	ConversationLiveMode,
	DeliveredAttachment,
	DeliveredDocumentAttachment,
	DeliveredImageAttachment,
	FlueClient,
	FlueConversationMessage,
	FlueConversationPart,
	FlueConversationSettlement,
	PromptUsage,
} from "@flue/sdk";
export {
	AgentSession,
	type AgentSnapshot,
	type AgentStatus,
	emptyAgentSnapshot,
	type FailedSend,
	type SendMessageOptions,
} from "./client/agent-session";

/** エージェントの経路の接頭辞の既定。rouar.json の agent.routes の既定と同じ */
export const DEFAULT_AGENT_ROUTE = "/agents";

export type AgentClientConfig = {
	/** 会話の URL の接頭辞。rouar.json の agent.routes の最初の値 */
	agentRoute?: string;
};

/**
 * 設定はプロセスかページの globalThis の Symbol の鍵に置く。
 * Nuxt のモジュールと Vite のプラグインが入れる値を、別の写しの @rouar/sdk からも読めるようにするため
 */
const CONFIG_KEY = Symbol.for("rouar.sdk.client");

type ConfigHolder = { [CONFIG_KEY]?: AgentClientConfig };

/** 会話の URL の接頭辞などを決める。Nuxt のモジュールと Vite のプラグインが呼ぶ */
export function configureAgentClient(config: AgentClientConfig): void {
	const holder = globalThis as ConfigHolder;
	holder[CONFIG_KEY] = { ...holder[CONFIG_KEY], ...config };
}

/** 今の会話の URL の接頭辞を返す。末尾の / は除く */
export function getAgentRoute(): string {
	const route =
		(globalThis as ConfigHolder)[CONFIG_KEY]?.agentRoute ?? DEFAULT_AGENT_ROUTE;
	return trimTrailingSlash(route) || DEFAULT_AGENT_ROUTE;
}

function trimTrailingSlash(value: string): string {
	return value.replace(/\/+$/, "");
}

/** `<接頭辞>/<エージェントの名前>/<会話の id>` を作る。名前と id は 1 つの区切りに符号化する */
export function agentConversationUrl(
	name: string,
	conversationId: string,
	options: { route?: string } = {},
): string {
	if (!name) throw new TypeError("[rouar] The agent name must not be empty.");
	if (!conversationId) {
		throw new TypeError("[rouar] The conversation id must not be empty.");
	}
	const route = trimTrailingSlash(options.route ?? getAgentRoute());
	return `${route}/${encodeURIComponent(name)}/${encodeURIComponent(conversationId)}`;
}

/** ブラウザで動いているか。SSR の間は false を返し、接続を開かせない */
export function isBrowser(): boolean {
	return (
		typeof (globalThis as { window?: unknown }).window !== "undefined" &&
		typeof (globalThis as { location?: unknown }).location !== "undefined"
	);
}

type SessionStorageLike = {
	getItem(key: string): string | null;
	setItem(key: string, value: string): void;
};

function sessionStorageOrUndefined(): SessionStorageLike | undefined {
	try {
		return (globalThis as { sessionStorage?: SessionStorageLike })
			.sessionStorage;
	} catch {
		// 第三者の cookie を断る設定などで、読むだけで例外になることがある
		return undefined;
	}
}

function randomId(): string {
	const crypto = (globalThis as { crypto?: { randomUUID?: () => string } })
		.crypto;
	if (crypto?.randomUUID) return crypto.randomUUID();
	return `${Date.now().toString(36)}${Math.random().toString(36).slice(2)}`;
}

/**
 * 会話の id を省いたときに使う id を返す。ブラウザで乱数の id を作り、sessionStorage に覚える。
 * 同じタブで読み直しても同じ会話を続け、別のタブでは別の会話にする。ブラウザの外では undefined を返す
 */
export function rememberedConversationId(
	name: string,
	options: { route?: string } = {},
): string | undefined {
	if (!isBrowser()) return undefined;
	const key = `rouar:conversation:${options.route ?? getAgentRoute()}/${name}`;
	const storage = sessionStorageOrUndefined();
	try {
		const saved = storage?.getItem(key);
		if (saved) return saved;
	} catch {
		// 読めなければ、覚えずに新しい id を使う
	}
	const id = randomId();
	try {
		storage?.setItem(key, id);
	} catch {
		// 容量の上限などで書けなくても、このページの間は同じ id を使う
	}
	return id;
}

export type CreateAgentSessionOptions = {
	/** 会話の URL。相対の URL はブラウザのオリジンで解決する */
	url?: string;
	/** 作ってある会話のクライアント。url より優先する */
	client?: FlueClient;
	/** 観測の方式。既定は sse */
	live?: ConversationLiveMode;
	/** 要求に使う fetch。テストや独自の転送に使う */
	fetch?: CreateFlueClientOptions["fetch"];
	/** すべての要求に足す見出し。同じオリジンの cookie は何もしなくても送られる */
	headers?: CreateFlueClientOptions["headers"];
};

function isAbsoluteUrl(url: string): boolean {
	try {
		new URL(url);
		return true;
	} catch {
		return false;
	}
}

/**
 * 1 つの会話の AgentSession を作る。まだ観測は始めないので、start() を呼ぶ。
 * 相対の URL をブラウザの外で渡したときと、URL もクライアントもないときは undefined を返す
 */
export function createAgentSession(
	options: CreateAgentSessionOptions,
): AgentSession | undefined {
	let client = options.client;
	if (!client) {
		if (options.url === undefined) return undefined;
		if (!isBrowser() && !isAbsoluteUrl(options.url)) return undefined;
		client = createFlueClient({
			url: options.url,
			...(options.fetch ? { fetch: options.fetch } : {}),
			...(options.headers ? { headers: options.headers } : {}),
		});
	}
	return new AgentSession(client, options.live ?? "sse");
}
