import type {
	AgentAbortResult,
	AgentConversationObservation,
	AgentConversationObservationPhase,
	AgentPromptOptions,
	AgentSendResult,
	ConversationLiveMode,
	DeliveredAttachment,
	DeliveredDocumentAttachment,
	FlueClient,
	FlueConversationMessage,
	FlueConversationSettlement,
	FlueConversationState,
} from "@flue/sdk";

export type AgentStatus =
	| "idle"
	| "connecting"
	| "submitted"
	| "streaming"
	| "error";

/** One locally-submitted message whose send failed, retained for retry UIs. */
export interface FailedSend {
	/** Id of the retained optimistic message in `messages` (the local id). */
	id: string;
	/** The text the user tried to send. */
	message: string;
	error: Error;
}

export interface AgentSnapshot {
	messages: FlueConversationMessage[];
	status: AgentStatus;
	historyReady: boolean;
	error: Error | undefined;
	/**
	 * Sends whose admission receipt never reached the client. Their optimistic
	 * messages remain in `messages` (keyed by `id`) so a UI can show them with
	 * a retry affordance.
	 */
	failedSends: FailedSend[];
	/** Terminal outcomes of the conversation's tracked submissions. */
	settlements: FlueConversationSettlement[];
}

/**
 * Options for one `sendMessage` call. Everything `client.send()` accepts
 * except the `message` itself is passed through untouched; `images` and
 * `documents` are folded into the delivered message's `attachments`.
 */
export type SendMessageOptions = Omit<AgentPromptOptions, "message"> & {
	images?: DeliveredAttachment[];
	documents?: DeliveredDocumentAttachment[];
};

type PendingSend = {
	localId: string;
	submissionId?: string;
	optimistic: FlueConversationMessage;
};

type AgentState = AgentSnapshot & {
	conversation: FlueConversationState | undefined;
	pendingSends: PendingSend[];
	failedOptimistic: FlueConversationMessage[];
	localMessageIds: { submissionId: string; localId: string }[];
	localSubmissionIds: string[];
	activeSubmissionIds: string[];
};

type AgentEvent =
	| {
			type: "local_send_submitted";
			localId: string;
			message: string;
			attachments?: DeliveredAttachment[];
	  }
	| { type: "local_send_admitted"; localId: string; submissionId: string }
	| { type: "local_send_failed"; localId: string; error: Error }
	| {
			type: "local_observation";
			conversation: FlueConversationState | undefined;
			phase: AgentConversationObservationPhase;
			error: Error | undefined;
	  };

export const emptyAgentState: AgentState = {
	messages: [],
	status: "idle",
	historyReady: false,
	error: undefined,
	failedSends: [],
	settlements: [],
	conversation: undefined,
	pendingSends: [],
	failedOptimistic: [],
	localMessageIds: [],
	localSubmissionIds: [],
	activeSubmissionIds: [],
};

function reduceAgentEvent(state: AgentState, event: AgentEvent): AgentState {
	switch (event.type) {
		case "local_send_submitted": {
			const settledIds = new Set(
				state.conversation?.settlements.map(
					(settlement) => settlement.submissionId,
				) ?? [],
			);
			return converge({
				...state,
				pendingSends: [
					...state.pendingSends,
					{ localId: event.localId, optimistic: optimisticMessage(event) },
				],
				localSubmissionIds: state.localSubmissionIds.filter(
					(id) => !settledIds.has(id),
				),
				failedSends: [],
				failedOptimistic: [],
				error: undefined,
			});
		}
		case "local_send_admitted":
			return converge({
				...state,
				pendingSends: state.pendingSends.map((send) =>
					send.localId === event.localId
						? { ...send, submissionId: event.submissionId }
						: send,
				),
				localMessageIds: [
					...state.localMessageIds,
					{ submissionId: event.submissionId, localId: event.localId },
				],
				localSubmissionIds: addUnique(
					state.localSubmissionIds,
					event.submissionId,
				),
				activeSubmissionIds: addUnique(
					state.activeSubmissionIds,
					event.submissionId,
				),
			});
		case "local_send_failed": {
			const failed = state.pendingSends.find(
				(send) => send.localId === event.localId,
			);
			return converge({
				...state,
				pendingSends: state.pendingSends.filter(
					(send) => send.localId !== event.localId,
				),
				...(failed
					? {
							failedOptimistic: [...state.failedOptimistic, failed.optimistic],
							failedSends: [
								...state.failedSends,
								{
									id: failed.localId,
									message: messageText(failed.optimistic),
									error: event.error,
								},
							],
						}
					: {}),
			});
		}
		case "local_observation": {
			if (event.phase === "error") {
				return { ...state, status: "error", error: event.error };
			}
			if (event.phase === "absent") {
				return converge({
					...state,
					conversation: undefined,
					historyReady: true,
				});
			}
			const connecting =
				event.phase === "loading" || event.phase === "connecting";
			if (event.conversation) {
				const merged = converge({
					...state,
					conversation: event.conversation,
					historyReady: true,
				});
				return connecting
					? {
							...merged,
							status: merged.status === "idle" ? "connecting" : merged.status,
							error: event.error ?? merged.error,
						}
					: merged;
			}
			return {
				...state,
				status: connecting ? "connecting" : state.status,
				error: event.error,
			};
		}
	}
}

function converge(state: AgentState): AgentState {
	const conversation = state.conversation;
	const settledIds = new Set(
		conversation?.settlements.map((settlement) => settlement.submissionId) ??
			[],
	);
	const localIdBySubmissionId = new Map(
		state.localMessageIds.map((entry) => [entry.submissionId, entry.localId]),
	);
	const canonical = (conversation?.messages ?? []).map((message) => {
		const localId =
			message.role === "user" && message.submissionId
				? localIdBySubmissionId.get(message.submissionId)
				: undefined;
		return localId ? { ...message, id: localId } : message;
	});
	const canonicalSubmissionIds = new Set(
		(conversation?.messages ?? [])
			.map((message) => message.submissionId)
			.filter((value): value is string => typeof value === "string"),
	);
	const pendingSends: PendingSend[] = [];
	const pendingEchoes: FlueConversationMessage[] = [];
	for (const pending of state.pendingSends) {
		if (
			pending.submissionId
				? canonicalSubmissionIds.has(pending.submissionId) ||
					settledIds.has(pending.submissionId)
				: false
		) {
			continue;
		}
		pendingSends.push(pending);
		pendingEchoes.push(pending.optimistic);
	}
	const messages = [...canonical, ...pendingEchoes, ...state.failedOptimistic];
	const ownStreaming = (conversation?.messages ?? []).some(
		(message) =>
			message.role === "assistant" &&
			message.parts.some(
				(part) =>
					(part.type === "text" || part.type === "reasoning") &&
					part.state === "streaming",
			),
	);
	const settlementBySubmissionId = new Map(
		(conversation?.settlements ?? []).map((settlement) => [
			settlement.submissionId,
			settlement,
		]),
	);
	const lastSettledLocalSubmission = [...state.localSubmissionIds]
		.reverse()
		.map((id) => settlementBySubmissionId.get(id))
		.find((settlement) => settlement !== undefined);
	const failedSettlement =
		lastSettledLocalSubmission?.outcome === "failed"
			? lastSettledLocalSubmission
			: undefined;
	const localActiveSubmissionIds = state.activeSubmissionIds.filter(
		(id) => !settledIds.has(id),
	);
	const observedActiveSubmissionIds = [...canonicalSubmissionIds].filter(
		(id) => !settledIds.has(id),
	);
	const hasActiveSubmission =
		localActiveSubmissionIds.length > 0 ||
		observedActiveSubmissionIds.length > 0;
	const hasFailedSend = state.failedSends.length > 0;
	const status: AgentStatus = failedSettlement
		? "error"
		: ownStreaming
			? "streaming"
			: pendingSends.length > 0
				? "submitted"
				: hasActiveSubmission
					? "streaming"
					: hasFailedSend
						? "error"
						: "idle";
	return {
		...state,
		messages,
		settlements: conversation?.settlements ?? [],
		pendingSends,
		activeSubmissionIds: localActiveSubmissionIds,
		status,
		error: failedSettlement
			? new Error(settlementError(failedSettlement.error))
			: status === "error" && hasFailedSend
				? state.failedSends[state.failedSends.length - 1]?.error
				: undefined,
	};
}

function optimisticMessage(event: {
	localId: string;
	message: string;
	attachments?: DeliveredAttachment[];
}): FlueConversationMessage {
	return {
		id: event.localId,
		role: "user",
		purpose: "user",
		display: "visible",
		parts: [
			{ type: "text", text: event.message, state: "done" },
			...(event.attachments ?? []).map((attachment) => ({
				type: "file" as const,
				mediaType: attachment.mimeType,
				url: `data:${attachment.mimeType};base64,${attachment.data}`,
				...(attachment.filename ? { filename: attachment.filename } : {}),
			})),
		],
	};
}

function messageText(message: FlueConversationMessage): string {
	const part = message.parts.find((value) => value.type === "text");
	return part && part.type === "text" ? part.text : "";
}

function addUnique(values: string[], value: string): string[] {
	return values.includes(value) ? values : [...values, value];
}

function settlementError(value: unknown): string {
	if (value && typeof value === "object" && "message" in value) {
		return String(value.message);
	}
	return "Agent submission failed";
}

/**
 * 1 つの会話の状態を、観測と楽観的な送信から組み立てる。
 * subscribe と getSnapshot は外部ストアの契約に合わせてあり、
 * 各フレームワークの包みはこの 2 つと sendMessage、refresh、abort を使う
 */
export class AgentSession {
	private state: AgentState = { ...emptyAgentState };
	private snapshot: AgentSnapshot = publicSnapshot(this.state);
	private readonly listeners = new Set<() => void>();
	private observation: AgentConversationObservation | undefined;
	private unsubscribeObservation: (() => void) | undefined;
	private active = false;
	private localId = 0;

	constructor(
		readonly client: FlueClient,
		private readonly live: ConversationLiveMode = "sse",
	) {}

	/** 観測を始める。2 回目からは何もしない */
	start(): void {
		if (this.active) return;
		this.active = true;
		this.observation = this.client.observe({ live: this.live });
		this.unsubscribeObservation = this.observation.subscribe(() =>
			this.applyObservation(),
		);
		this.applyObservation();
	}

	subscribe = (listener: () => void): (() => void) => {
		this.listeners.add(listener);
		return () => {
			this.listeners.delete(listener);
		};
	};

	getSnapshot = (): AgentSnapshot => this.snapshot;

	/**
	 * Re-runs the observation's history catch-up and resumes live updates.
	 * No-op before `start()` or after `dispose()`.
	 */
	refresh = (): void => {
		this.observation?.refresh();
	};

	sendMessage = async (
		message: string,
		options: SendMessageOptions = {},
	): Promise<AgentSendResult> => {
		const localId = `local:${++this.localId}`;
		const { images, documents, ...sendOptions } = options;
		const attachments = [...(images ?? []), ...(documents ?? [])];
		this.dispatch({
			type: "local_send_submitted",
			localId,
			message,
			attachments,
		});
		try {
			const receipt = await this.client.send({
				...sendOptions,
				message: {
					kind: "user",
					body: message,
					...(attachments.length ? { attachments } : {}),
				},
			});
			this.dispatch({
				type: "local_send_admitted",
				localId,
				submissionId: receipt.submissionId,
			});
			if (this.observation?.getSnapshot().phase === "absent") {
				this.observation.refresh();
			}
			return receipt;
		} catch (error) {
			this.dispatch({
				type: "local_send_failed",
				localId,
				error: toError(error),
			});
			throw error;
		}
	};

	/** 会話の実行中と待ちの仕事を止める。止めた結果は観測の settlements に届く */
	abort = (options?: { signal?: AbortSignal }): Promise<AgentAbortResult> =>
		this.client.abort(options);

	dispose(): void {
		if (!this.active) return;
		this.active = false;
		this.unsubscribeObservation?.();
		this.unsubscribeObservation = undefined;
		this.observation?.close();
		this.observation = undefined;
	}

	private applyObservation(): void {
		const observed = this.observation?.getSnapshot();
		if (!observed) return;
		this.dispatch({
			type: "local_observation",
			conversation: observed.conversation,
			phase: observed.phase,
			error: observed.error,
		});
	}

	private dispatch(event: AgentEvent): void {
		const next = reduceAgentEvent(this.state, event);
		if (next === this.state) return;
		this.state = next;
		this.snapshot = publicSnapshot(this.state);
		for (const listener of this.listeners) listener();
	}
}

function publicSnapshot(state: AgentState): AgentSnapshot {
	return {
		messages: state.messages,
		status: state.status,
		historyReady: state.historyReady,
		error: state.error,
		failedSends: state.failedSends,
		settlements: state.settlements,
	};
}

function toError(error: unknown): Error {
	return error instanceof Error ? error : new Error(String(error));
}

/** 会話の URL がないときや SSR の間に返す、空の状態 */
export const emptyAgentSnapshot: AgentSnapshot =
	publicSnapshot(emptyAgentState);
